/**
 * The types `data/themes/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    ThemeItem, ThemeBonusGroup, ThemeBonusCatalogEntry, ThemeCategoryKey, ThemeCategoryDefinition, ThemePassiveFormulaTerm
 * depends    —
 * used by    src/data/themes/bonus-catalog, src/data/themes/catalog, src/data/themes/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from bonus-catalog.ts

export type ThemeItem = { name: string, event?: string, pass?: string }

/**
 * How themes are grouped for bonus purposes.
 *
 * Three related types exist and they are not interchangeable — check which one
 * you want before importing:
 *
 * - **`ThemeBonusGroup`** (here) — the seven catalog groups a theme is listed
 *   under, each with one passive coin rate. Includes `MILESTONE`, which is how
 *   a tower theme was earned rather than a separate cosmetic slot.
 * - **`ThemeCategoryKey`** (`themes-catalog.ts`) — the four categories the coin
 *   formula multiplies over. No milestone: those themes count as tower.
 * - **`ThemeCatalogCategory`** (`save/catalogs/themes.ts`) — the categories a
 *   save file stores unlocks under, including `song` and `profileBanner`.
 *
 * A test asserts the four overlapping rates agree with the coin formula.
 * Unifying all three is worthwhile but would change save parsing, so it has
 * not been attempted here.
 */
export type ThemeBonusGroup =
  | 'TOWER'
  | 'BACKGROUND'
  | 'MILESTONE'
  | 'SONGS'
  | 'GUARDIAN'
  | 'MENU'
  | 'PROFILE_BANNER'

export type ThemeBonusCatalogEntry = {
  name: string
  category: ThemeBonusGroup
  bonus: string
}

// from catalog.ts

export type ThemeCategoryKey = 'tower' | 'background' | 'menu' | 'guardian'

export interface ThemeCategoryDefinition {
  key: ThemeCategoryKey
  label: 'Tower' | 'Background' | 'Menu' | 'Guardian'
  unlockSources: readonly string[]
  /** Percentage points of coin bonus per theme owned in this category. */
  passiveCoinBonusPerOwnedPercent: number
  passiveCoinBonusPerOwnedDisplay: string
}

export interface ThemePassiveFormulaTerm {
  category: ThemeCategoryKey
  label: ThemeCategoryDefinition['label']
  /** The percentage expressed as a multiplier coefficient (0.4% -> 0.004). */
  coefficient: number
}
